const incoming = $json.body ?? $json;
const nestedPayload = incoming.payload && typeof incoming.payload === 'object' ? incoming.payload : {};
const normalized = {...nestedPayload, ...incoming};
normalized.payload = nestedPayload.payload ?? nestedPayload;
normalized.mode = normalized.mode || 'dry_run';
normalized.action = normalized.action || 'run_lifecycle';
normalized.tool_results = Array.isArray(normalized.tool_results) ? normalized.tool_results : [];
normalized.desired_tools = Array.isArray(normalized.desired_tools) ? normalized.desired_tools : null;
delete normalized.skipped_tool;
const toolName = 'tool_job_intake';
const shouldRun = !normalized.desired_tools || normalized.desired_tools.includes(toolName);
if (!shouldRun) {
  const results = [...normalized.tool_results, {tool: toolName, status: 'skipped', reason: 'not selected for action'}];
  return [{json: {...normalized, tool_results: results, skipped_tool: toolName}}];
}
const bodyForSql = {...normalized, requested_outputs: normalized.requested_outputs || []};
return [{json: {...normalized, current_stage: toolName, live_mode: normalized.mode === 'live', payload_sql: JSON.stringify(bodyForSql).replace(/'/g, "''")}}];

const output = {...$json};
delete output.skipped_tool;
return [{json: output}];

const base = $node['Normalize And Auth'].json;
const current = $json;
const status = current.status || 'intake_complete';
const parseJson = (value, fallback) => {
  try { return typeof value === 'string' ? JSON.parse(value) : (value ?? fallback); } catch { return fallback; }
};
const requestedOutputs = parseJson(current.requested_outputs_json, base.requested_outputs || []);
const clientProfile = parseJson(current.client_profile_json, base.client_profile || null);
const results = [...(base.tool_results || []), {tool: 'tool_job_intake', status, job_id: current.job_id || base.job_id || ''}];
return [{json: {...base, ...current, requested_outputs: requestedOutputs, client_profile: clientProfile, client_profile_id: current.client_profile_id || base.client_profile_id, approval_policy: current.approval_policy || base.approval_policy, job_id: current.job_id || base.job_id, status, tool_results: results, current_stage: 'tool_job_intake'}}];
